@pytest.mark.parametrize('scheme', ('http+unix', 'HTTP+unix', 'http+custom'))
@pytest.mark.parametrize('as_bytes', (False, True))
@pytest.mark.parametrize('use_session', (False, True))
@pytest.mark.parametrize('query', ('', '?existing=value'))
def test_http_custom_scheme_params(self, scheme, as_bytes, use_session, query):
    url = scheme + '://%2Fvar%2Frun%2Fsocket/path' + query + '#fragment'
    if as_bytes:
        url = url.encode('utf-8')
    request = requests.Request('GET', url, params=[('a', 'hello world')])
    if use_session:
        prepared = requests.Session().prepare_request(request)
    else:
        prepared = request.prepare()
    expected_query = query + '&' if query else '?'
    assert prepared.url == (
        scheme.lower() + '://%2Fvar%2Frun%2Fsocket/path' +
        expected_query + 'a=hello+world#fragment'
    )

